import { insertarPlantilla } from "./word";

const boton = document.getElementById("seleccionar");
const input = document.getElementById("documento") as HTMLInputElement;
let documentoSeleccionado: File | null = null;
const documentos: File[] = [];

boton?.addEventListener("click",()=>{
	input.click();
})

input.addEventListener("change", async()=>{
	documentoSeleccionado = input.files?.[0] ?? null;

	if (documentoSeleccionado) {
		const existe = documentos.some(
			documento => documento.name === documentoSeleccionado.name
		);

	if (!existe) {
	    documentos.push(documentoSeleccionado);
	    await guardarPlantilla(documentoSeleccionado);
	}
		

		documentoSeleccionado = null;
		mostrarDocumentos();
	}
})

function mostrarDocumentos() {
    const lista = document.getElementById("plantillas");

    if (!lista) return;

    lista.innerHTML = "";

    documentos.forEach(documento => {
        const elemento = document.createElement("li");

        elemento.textContent = documento.name;

        elemento.addEventListener("click", async () => {
            const base64 = await convertirBase64(documento);
            await insertarPlantilla(base64);
        });

        const botonEliminar = document.createElement("button");

        botonEliminar.textContent = "Eliminar";

		botonEliminar.addEventListener("click", async (event) => {
		    event.stopPropagation();

		    const indice = documentos.indexOf(documento);

		    if (indice !== -1) {
		        await eliminarPlantilla(documento.name);
		        documentos.splice(indice, 1);
		        mostrarDocumentos();
		    }
		});

        elemento.appendChild(botonEliminar);

        lista.appendChild(elemento);
    });
}

function convertirBase64(archivo: File): Promise<string> {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();

        reader.onload = () => {
            const resultado = reader.result as string;
            resolve(resultado.split(",")[1]);
        };

        reader.onerror = () => reject(reader.error);

        reader.readAsDataURL(archivo);
    });
}

function abrirBaseDatos(): Promise<IDBDatabase> {
    return new Promise((resolve, reject) => {
        const solicitud = indexedDB.open("PageVaultDB", 1);

        solicitud.onupgradeneeded = () => {
            const db = solicitud.result;

            if (!db.objectStoreNames.contains("plantillas")) {
                db.createObjectStore("plantillas", {
                    keyPath: "nombre"
                });
            }
        };

        solicitud.onsuccess = () => {
            resolve(solicitud.result);
        };

        solicitud.onerror = () => {
            reject(solicitud.error);
        };
    });
}

async function guardarPlantilla(documento: File) {
    const db = await abrirBaseDatos();

    const transaccion = db.transaction("plantillas", "readwrite");
    const almacen = transaccion.objectStore("plantillas");

    almacen.put({
        nombre: documento.name,
        archivo: documento
    });
}

async function cargarPlantillas() {
    const db = await abrirBaseDatos();

    const transaccion = db.transaction("plantillas", "readonly");
    const almacen = transaccion.objectStore("plantillas");

    const solicitud = almacen.getAll();

    solicitud.onsuccess = () => {
        solicitud.result.forEach(plantilla => {
            documentos.push(plantilla.archivo);
        });

        mostrarDocumentos();
    };
}

async function eliminarPlantilla(nombre: string) {
    const db = await abrirBaseDatos();

    const transaccion = db.transaction("plantillas", "readwrite");
    const almacen = transaccion.objectStore("plantillas");

    almacen.delete(nombre);
}
window.addEventListener("error", (event) => {
    console.error("ERROR GLOBAL:", event.error);
    console.error("MENSAJE:", event.message);
    console.error("ARCHIVO:", event.filename);
    console.error("LINEA:", event.lineno);
    console.error("COLUMNA:", event.colno);
});

window.addEventListener("unhandledrejection", (event) => {
    console.error("PROMESA RECHAZADA:", event.reason);
});

Office.onReady(() => {
    cargarPlantillas();
});